import{_ as e,o as r,c as t,a4 as i}from"./chunks/framework.CzJ_HCFe.js";const m=JSON.parse('{"title":"Pilgrimage Source Profile","description":"","frontmatter":{},"headers":[],"relativePath":"reference/29-pilgrimage-profile.md","filePath":"reference/29-pilgrimage-profile.md","lastUpdated":1787887572000}'),o={name:"reference/29-pilgrimage-profile.md"};function n(s,a,l,c,u,h){return r(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="pilgrimage-source-profile" tabindex="-1">Pilgrimage Source Profile <a class="header-anchor" href="#pilgrimage-source-profile" aria-label="Permalink to &quot;Pilgrimage Source Profile&quot;">​</a></h1><h2 id="claim-and-authority" tabindex="-1">Claim and authority <a class="header-anchor" href="#claim-and-authority" aria-label="Permalink to &quot;Claim and authority&quot;">​</a></h2><p>The <code>pilgrimage</code> activity is linked to <code>muhurta.pilgrimage</code>. Its authority is B. V. Raman&#39;s <em>Muhurtha</em>, Chapter XIV, &quot;Journeys&quot; and &quot;Pilgrimage,&quot; printed pages 60-62 (PDF pages 64-66 in the registered edition). Raman is a modern secondary authority, not scripture.</p><p>The pilgrimage paragraph explicitly says to follow the preceding journey rules. It then adds two activity-specific conditions: Guru should occupy Lagna or the 9th house, and months of Guru combustion should be avoided.</p><h2 id="automated-and-manual-criteria" tabindex="-1">Automated and manual criteria <a class="header-anchor" href="#automated-and-manual-criteria" aria-label="Permalink to &quot;Automated and manual criteria&quot;">​</a></h2><p>The incorporated journey section says Chaturdashi and Full/New Chandra days must be avoided, so the profile rejects Tithi numbers 14 and 15. It calls ten Nakshatras the best for satisfactory completion and early return; these earn a preference rather than becoming an exclusive admission list. Guru combustion is a hard exclusion. Guru in Lagna or the 9th remains a visible manual chart check.</p><p>The existing Vishti-Karana exclusion agrees with the separately cited general Panchanga-Suddhi rule. The existing Chara-Lagna bonus remains a project heuristic: Raman names six individual favorable journey Rasis rather than the Chara class. This claim does not lend that bonus textual authority.</p><p>Python, MCP, and the generated browser contract publish the same claim ID, automated constraints, Nakshatra preferences, and manual check. The browser enforces Guru combustion from the per-city Lagna sidecar and fails closed when that screening datum is unavailable.</p>',8)])])}const p=e(o,[["render",n]]);export{m as __pageData,p as default};
